    "Starting inventory": "Inventario inicial",
    "Your first interaction": "Tu primera interacción",
    "Every map starts with the starting room. Create it with the button on the left.": "Todo mapa empieza por la sala inicial. Créala con el botón de la izquierda.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Elige una loseta en la paleta y ponla en el tablero; pulsa R para girarla. Por ahora, coloca dos losetas distintas: se sacarán de la caja y se prepararán durante la partida.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "El botón Héroe (H) define las casillas de salida de nuestros aventureros. Selecciona de 2 a 4 casillas en la sala inicial.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Para revelar el mapa poco a poco, necesitamos crear una sala nueva. Aparece cuando se usa un objeto, programando un disparador que abre una sala. Probemos: haz clic en el botón Objeto (O) y elige una puerta. Luego añade un disparador “Abrir una sala”.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Has creado tu primera interacción con el escenario. En el juego, el héroe abrirá la puerta y liberará las losetas de la sala siguiente. Ahora, llenemos esa sala: pon un cofre en una sala y programa un disparador que dé ítems a los jugadores (los demás botones y disparadores esperan a esto).",
    "📂 Import a save of the game (.sav)": "📂 Importar una partida guardada del juego (.sav)",
    "Clear all": "Vaciar todo",
    "Search an item…": "Buscar un ítem…",
    "Only what the party has": "Solo lo que tiene el grupo",
