    "Imported from the save": "Importado de la partida guardada",
    "This file is not a save of the game.": "Este archivo no es una partida guardada del juego.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Para un grupo de veteranos: lo que ya tiene al empezar la campaña, ganado en batallas anteriores. El grupo lo recibe cuando empieza la campaña. Los ítems vienen del Taller (pestañas Ítems y Armas), las habilidades de la pestaña Habilidades (o las del juego). Las reservas de ítems de los mapas generados dejan fuera los ítems únicos que el grupo ya tiene, y el juego nunca da un ítem dos veces.",
