    "Elements with no link": "Elementos sin vínculo",
    "I know my way around": "Ya me manejo",
    "Are you sure about that?": "¿Seguro?",
    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "El tutorial te guía por el editor paso a paso. Si alguna vez quieres volver a verlo, puedes repetirlo desde ⚙ Ajustes.",
    "Yes, skip it": "Sí, omitirlo",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "¿Omitir el tutorial? Todo se desbloquea ahora. Si cambias de idea, ⚙ Ajustes puede repetirlo.",
    "Right here!": "¡Aquí mismo!",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "Con Héroe (H), haz clic en las casillas donde empiezan los héroes: elige de 2 a 4 casillas en la sala inicial.",
    "Nice work!": "¡Buen trabajo!",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "La primera sala ya está ligada a su puerta: cuando un héroe la abre, la sala siguiente aparece en la mesa. Ahora añadamos un cofre y hagamos que entregue algunos ítems al grupo. Los demás botones y disparadores pueden esperar su turno.",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "Coloca un Cofre (Objeto) en una sala, selecciónalo y añade el disparador “Dar o quitar un ítem”. Elige qué da al grupo cuando se abre.",
    "A brand-new room": "Una sala recién estrenada",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "La puerta ha venido con su programación y ya ha creado una sala nueva ligada a ella. Coloca sus losetas cuando quieras. Ahora, unos monstruos: el botón Enemigo está desbloqueado.",
    "Let’s put some monsters in a room: press Enemy (E).": "Pongamos unos monstruos en una sala: pulsa Enemigo (E).",
    "Ops!": "¡Ups!",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "En el Taller, pulsa “Importar…” y trae unos 10 monstruos del juego para este mapa.",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "Echa un vistazo a los otros talleres si quieres, y luego vuelve a Salas (◂ Salas).",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "Ahora el generador de salas. Pulsa ✦ Generar sala y haz clic en la puerta que conectará con la sala nueva.",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "Primero mueve la sala (arrástrala o usa las flechas) o gírala (R). “Usar esta” se activa en cuanto la sala se haya movido.",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "Has construido salas a mano, has programado objetos, has traído monstruos y has generado una sala. Ahora solo falta la campaña: une mapas en el mapa del mundo, con escenas, elecciones y recompensas entre ellos. Pulsa “Empezar una campaña” y el resto del editor se abre.",
    "Press “Start a campaign”: everything is unlocked from there.": "Pulsa “Empezar una campaña”: a partir de ahí todo se desbloquea.",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "Explora el flujo de la historia, una escena (y sus cajas), el inventario inicial y las variables de la historia. Luego vuelve a Salas (◂ Salas) para terminar.",
    "Open the Workshop": "Abrir el Taller",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "Las demás condiciones más precisas de esta proeza en el juego (primer ataque de la ronda, otros héroes…) se mantienen como están.",
    "Otherwise the scene is skipped (the story goes on).": "Si no, la escena se salta (la historia sigue).",
    "Pick a box on the left, or add one.": "Elige una caja a la izquierda, o añade una.",
    "Pick a feat on the left, import one from the game, or write a new one.": "Elige una proeza a la izquierda, importa una del juego o escribe una nueva.",
    "Pick a kind on the left.": "Elige un tipo a la izquierda.",
    "Pick a recipe on the left, import one from the game, or write a new one.": "Elige una receta a la izquierda, importa una del juego o escribe una nueva.",
    "Pick another object": "Elegir otro objeto",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "Los pilares van en los encajes de una loseta elevada de esta sala en el nivel {n} (los puntos de sus bordes).",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "Los pilares sostienen losetas elevadas: elige primero el nivel de esa loseta (de {n} a {n}) en la barra.",
    "Place the city…": "Colocar la ciudad…",
