    "The platform is a box standing on the floor: it needs no pillars.": "La plataforma es una caja apoyada en el suelo: no necesita pilares.",
    "The rune: damage, damage types and power": "La runa: daño, tipos de daño y poder",
    "First effect: an ability that may trigger on hits": "Primer efecto: una capacidad que puede activarse al acertar",
    "Second effect: another ability that may trigger on hits": "Segundo efecto: otra capacidad que puede activarse al acertar",
    "The spaces work together, by the game's rule for random spawns: one budget of points for all of them (intensity ÷ {n} × heroes × {n} × progression, Map setup › Balancing) decides how many monsters enter and how strong. All may enter, or just one strong monster.": "Las casillas funcionan juntas, con la regla del juego para las apariciones aleatorias: un presupuesto de puntos para todas (intensidad ÷ {n} × héroes × {n} × progresión, Configurar mapa › Equilibrio) decide cuántos monstruos entran y con qué fuerza. Pueden entrar todos, o solo un monstruo fuerte.",
    "The workshop has no items yet.": "El Taller aún no tiene ítems.",
