    "Used, it leaves the board (like a point of interest in the game).": "Al usarse, sale del tablero (como un punto de interés en el juego).",
    "Using this object counts as an objective of the room (listed and ticked). Older maps only: use “{q}”.": "Usar este objeto cuenta como un objetivo de la sala (listado y marcado). Solo mapas antiguos: usa “{Q}”.",
