    "Worn by a hero: a card with its rule, kept in the party’s inventory.": "Lo lleva un héroe: una carta con su regla, guardada en el inventario del grupo.",
    "Writes the .bmap (download), then clears.": "Escribe el .bmap (descarga) y luego limpia.",
    "✎ Draw a road": "✎ Trazar un camino",
    "✓ Finish this road": "✓ Terminar este camino",
    "Tiles can stand at levels 1, 2 and 3 (the level buttons) on": "Las losetas pueden estar en los niveles 1, 2 y 3 (los botones de nivel) sobre",
    "; the app counts the pillars your boxes have.": "; la aplicación cuenta los pilares que tienen tus cajas.",
    "pillars (P)": "pilares (P)",
    "Counts": "Recuentos",
    "keep a number during the map (keys found, seals broken): triggers add to them, and a map objective can wait for the total.": "guardan un número durante el mapa (llaves encontradas, sellos rotos): los disparadores les suman, y un objetivo del mapa puede esperar al total.",
    "Export map": "Exportar mapa",
    "The": "El",
    "Workshop (⚒)": "Taller (⚒)",
    "Map setup": "Configurar mapa",
    "Start a campaign": "Empezar una campaña",
    "Press": "Pulsa",
    "3D": "3D",
    "Hero (H)": "Héroe (H)",
    "Enemy (E)": "Enemigo (E)",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Cuando empieza la sala, el juego llena estas casillas con su propia regla para apariciones aleatorias: puntos = intensidad ÷ {n} × héroes × {n} × progresión",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Cuando se abre la sala, el juego llena estas casillas con su propia regla para apariciones aleatorias: puntos = intensidad ÷ {n} × héroes × {n} × progresión",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Cuando se abre la sala, el juego llena estas casillas con su propia regla para apariciones aleatorias: puntos = intensidad ÷ {n} × héroes × {n} × progresión; toma el nivel más alto de la franja del mapa que pagan los puntos (costes {n}, {n}, {n}, {n}, {n}, {n}…), y entran monstruos de la reserva que tienen ese nivel, uno por casilla (hasta {n}), mientras duren los puntos. Los puntos sobrantes van a la siguiente sala equilibrada. Pueden entrar todos, o solo un monstruo fuerte.",
    "{n} balanced spaces in this room": "{n} casillas equilibradas en esta sala",
    "{n} monsters, tier {n}": "{n} monstruos, nivel {n}",
    "{n} monster, tier {n}": "{n} monstruo, nivel {n}",
    "{n} monsters, tier {n} (no more miniatures)": "{n} monstruos, nivel {n} (no hay más miniaturas)",
    "none: no free miniature": "ninguno: no hay miniatura libre",
    "Room {n} · space {n},{n}": "Sala {n} · casilla {n},{n}",
    "{n} rooms · side quest": "{n} salas · misión secundaria",
    "A change applies while this campaign is played, to every copy of the part, also the ones bought or found later.": "Un cambio se aplica mientras se juega esta campaña, a todas las copias de la parte, incluidas las que se compren o encuentren después.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Elige un tipo de arma, luego sus cabezas, astas o empuñaduras. Lo que cambies se aplica mientras se juega esta campaña (a todas las copias de la parte, incluidas las que se compren o encuentren después); lo que dejes queda como en el juego.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later)": "Elige un tipo de arma, luego sus cabezas, astas o empuñaduras. Lo que cambies se aplica mientras se juega esta campaña (a todas las copias de la parte, incluidas las que se compren o encuentren después)",
    "Here you prepare the monsters of this campaign. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "Aquí preparas los monstruos de esta campaña. Solo los monstruos listados aquí se pueden poner en el tablero o sortear de la reserva de aparición.",
    "A short list is easier to balance and to test; add more as the campaign grows.": "Una lista corta es más fácil de equilibrar y probar; añade más a medida que crece la campaña.",
    "add more as the campaign grows.": "añade más a medida que crece la campaña.",
    "Here you choose the items of this campaign: import them from the game, change them (name, rarity, value, damage, abilities) or create your own. Only the items listed here can be dropped by monsters, found or given by triggers, and the": "Aquí eliges los ítems de esta campaña: impórtalos del juego, cámbialos (nombre, rareza, valor, daño, capacidades) o crea los tuyos. Solo los ítems listados aquí pueden soltarlos los monstruos, encontrarse o darse por disparadores, y la",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "Los ítems fuertes al principio hacen fáciles los combates; demasiado pocos, o débiles, dejan a los héroes por detrás de los monstruos. Elígelos a propósito, pensando en el progreso de los héroes a lo largo de la campaña.",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "demasiado pocos, o débiles, dejan a los héroes por detrás de los monstruos. Elígelos a propósito, pensando en el progreso de los héroes a lo largo de la campaña.",
    "Each sheet changes one of the six heroes of the game while this campaign is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Cada ficha cambia uno de los seis héroes del juego mientras se juega esta campaña: nombre, retrato y figura animada. Sus armas están en la pestaña Armas. Lo que dejes como está queda como en el juego.",
    "The item workshop": "El taller de ítems",
    "The monster workshop": "El taller de monstruos",
    "is what random-item triggers draw from.": "es de donde sortean los disparadores de ítem aleatorio.",
    "The selection of available items is essential for the balance of the game.": "La selección de ítems disponibles es esencial para el equilibrio de la partida.",
    "The party has it from the start of the campaign (the heroes pick it in the hero choice)": "El grupo lo tiene desde el inicio de la campaña (los héroes lo eligen en la elección de héroes)",
