    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "la intensidad de las salas con monstruos y de los disparadores que llaman monstruos de la reserva, todas con el mismo paso (de −6 a +6, siempre dentro de 1 a 10);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "los niveles para 1–2, 3 y 4 héroes de los monstruos colocados a mano, con la regla del juego (como ⚖ Equilibrar en un monstruo).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "la progresión de la campaña, las reservas de monstruos e ítems, los propios monstruos, los objetos, los disparadores y los textos.",
