    "filter…": "filtrar…",
    "in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger.": "en cualquier otra sala entran automáticamente cuando se abre la sala. Los monstruos que llegan después (en una sala ya abierta) usan un disparador “{Q}”.",
    "it holds nothing up.": "no sostiene nada.",
    "level {n}": "nivel {n}",
    "level {n} (ribbon). Greyed tiles are already in this room": "nivel {n} (barra). Las losetas en gris ya están en esta sala",
