    ", or brought by a trigger when something happens.": ", o traídos por un disparador cuando pasa algo.",
    "Checklist": "Lista de comprobación",
    "Click a piece to edit it": "Haz clic en una pieza para editarla",
    "Click the spaces where the heroes start (starting room only, {n} to {n}). (H)": "Haz clic en las casillas donde empiezan los héroes (solo la sala inicial, de {n} a {n}). (H)",
