    "Create the starting room": "Crear la sala inicial",
    "Create the starting room.": "Crea la sala inicial.",
    "Doors, chests, tokens… Any object can carry triggers and requirements. Staircases and bridges are floor: they may go off the tiles. (O)": "Puertas, cofres, fichas… Cualquier objeto puede llevar disparadores y requisitos. Las escaleras y los puentes son suelo: pueden salir de las losetas. (O)",
    "Edit": "Editar",
    "Erase the rooms of this map (tiles, objects, monsters, hero spaces, triggers). The workshop, the map setup and the campaign stay. Asks first and offers to export.": "Borra las salas de este mapa (losetas, objetos, monstruos, casillas de héroe, disparadores). El Taller, la configuración del mapa y la campaña se conservan. Pregunta antes y ofrece exportar.",
