    "Monsters placed in a room. In the starting room they are there from the start": "Monstruos colocados en una sala. En la sala inicial están allí desde el principio",
    "Monsters placed in a room. In the starting room they are there from the start; in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger. (E)": "Monstruos colocados en una sala. En la sala inicial están allí desde el principio; en cualquier otra sala entran automáticamente cuando se abre la sala. Los monstruos que llegan después (en una sala ya abierta) usan un disparador “{Q}”. (E)",
    "Name of the map": "Nombre del mapa",
    "No room yet": "Aún no hay sala",
    "Paste the copied piece (Ctrl+V): click where it goes": "Pega la pieza copiada (Ctrl+V): haz clic donde va",
    "Pick a tile in the palette and click the board. R rotates. Each physical tile (side A or B) only once per room; same-level tiles cannot overlap. Underlays go under the tiles. (T)": "Elige una loseta en la paleta y haz clic en el tablero. R gira. Cada loseta física (cara A o B) solo una vez por sala; las losetas del mismo nivel no pueden superponerse. Las capas inferiores van bajo las losetas. (T)",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars": "Elige el nivel de la loseta elevada en la barra y haz clic en uno de sus encajes (los puntos: entre dos casillas en un borde recto, nunca en una esquina). El pilar pertenece a esa loseta y entra en el juego con ella. Las losetas de nivel {n} admiten pilares bajos, medianos o altos",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars; level {n} medium or tall; level {n} tall. (P)": "Elige el nivel de la loseta elevada en la barra y haz clic en uno de sus encajes (los puntos: entre dos casillas en un borde recto, nunca en una esquina). El pilar pertenece a esa loseta y entra en el juego con ella. Las losetas de nivel {n} admiten pilares bajos, medianos o altos; las de nivel {n}, medianos o altos; las de nivel {n}, altos. (P)",
    "Place": "Colocar",
    "Place an object (a door, a lever, a chest…) and give it the trigger “{q}” to open the next room: the board is revealed little by little, as the players explore.": "Coloca un objeto (una puerta, una palanca, un cofre…) y dale el disparador “{Q}” para abrir la sala siguiente: el tablero se va revelando poco a poco, a medida que los jugadores exploran.",
    "Rooms": "Salas",
