    "Balance: sets the tiers for {n}–{n}, {n} and {n} heroes by the game's points (room intensity ÷ {n} × heroes × {n} × progression, shared by the monsters placed in this room), each one above the other": "Equilibrar: define los niveles para {n}–{n}, {n} y {n} héroes con los puntos del juego (intensidad de la sala ÷ {n} × héroes × {n} × progresión, repartidos entre los monstruos colocados en esta sala), cada uno por encima del otro",
    "Edit in the workshop": "Editar en el Taller",
    "Like the game's bosses (Levirax: tier {n}, {n} or {n} for {n}, {n} or {n} heroes). The difficulty (Journey, Heroic, Warfare) still applies on top.": "Como los jefes del juego (Levirax: nivel {n}, {n} o {n} para {n}, {n} o {n} héroes). La dificultad (Viaje, Heroica, Guerra) se sigue aplicando encima.",
    "Room intensity": "Intensidad de la sala",
    "Tier": "Nivel",
    "Tier by the number of heroes": "Nivel según el número de héroes",
    "Triggers of this monster: they run every time it is defeated, after the game’s own effects (loot, objectives). Taking it off with “{q}” does not count.": "Disparadores de este monstruo: se ejecutan cada vez que es derrotado, después de los efectos propios del juego (botín, objetivos). Quitarlo con “{Q}” no cuenta.",
