    "Clear the map?": "¿Limpiar el mapa?",
    "Clear without exporting": "Limpiar sin exportar",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop, the other maps, the campaign and the author stay. Files already exported stay in the folder.": "Esto borra la(s) {n} sala(s) del mapa “{Q}”: losetas, pilares, objetos, monstruos, casillas de héroe y sus disparadores, además del nombre y la configuración del mapa (textos, música, misión, reservas, contadores). El Taller, los otros mapas, la campaña y el autor se conservan. Los archivos ya exportados siguen en la carpeta.",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop and the author stay. Files already exported stay in the folder.": "Esto borra la(s) {n} sala(s) del mapa “{Q}”: losetas, pilares, objetos, monstruos, casillas de héroe y sus disparadores, además del nombre y la configuración del mapa (textos, música, misión, reservas, contadores). El Taller y el autor se conservan. Los archivos ya exportados siguen en la carpeta.",
    "The map has nothing to clear.": "El mapa no tiene nada que limpiar.",
    "Do you want to export it before clearing?": "¿Quieres exportarlo antes de limpiar?",
    "Everything not exported is lost.": "Todo lo que no se exporte se pierde.",
    "Export, then clear": "Exportar y luego limpiar",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers. The workshop, the map setup (name, texts, music, pools), the other maps and the campaign stay. Files already exported stay in the folder.": "Esto borra la(s) {n} sala(s) del mapa “{Q}”: losetas, pilares, objetos, monstruos, casillas de héroe y sus disparadores. El Taller, la configuración del mapa (nombre, textos, música, reservas), los otros mapas y la campaña se conservan. Los archivos ya exportados siguen en la carpeta.",
    "Writes the .bcamp and its maps (download), then clears.": "Escribe el .bcamp y sus mapas (descarga) y luego limpia.",
