    "What the game would do": "Lo que haría el juego",
    "When the group is defeated": "Cuando el grupo es derrotado",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Cuando empieza la sala, el juego llena estas casillas con su propia regla para apariciones aleatorias: puntos = intensidad ÷ {n} × héroes × {n} × progresión; toma el nivel más alto de la franja del mapa que pagan los puntos (costes {n}, {n}, {n}, {n}, {n}, {n}…), y entran monstruos de la reserva que tienen ese nivel, uno por casilla (hasta {n}), mientras duren los puntos. Los puntos sobrantes van a la siguiente sala equilibrada. Pueden entrar todos, o solo un monstruo fuerte.",
    "change": "cambiar",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "toma el nivel más alto de la franja del mapa que pagan los puntos (costes {n}, {n}, {n}, {n}, {n}, {n}…), y entran monstruos de la reserva que tienen ese nivel, uno por casilla (hasta {n}), mientras duren los puntos. Los puntos sobrantes van a la siguiente sala equilibrada. Pueden entrar todos, o solo un monstruo fuerte.",
    "{n} (= spaces, default)": "{n} (= casillas, predeterminado)",
    "{n} balanced space in this room": "{n} casilla equilibrada en esta sala",
    "{n} hero": "{n} héroe",
    "{n} monster, tier {n} (too few points: the minimum)": "{n} monstruo, nivel {n} (muy pocos puntos: el mínimo)",
    "Opened by:": "La abre:",
    "Remove this room": "Quitar esta sala",
    "Text when revealed": "Texto al revelarse",
    "Text after the room is set up": "Texto después de preparar la sala",
    "Text after the board is set up": "Texto después de preparar el tablero",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Lo que los héroes encuentran en ella: una persona, un objeto (las fichas de interacción)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "La loseta {n} está en otra sala: reutilizarla aquí exige quitar antes esa sala",
    "give one an “{q}” trigger": "dale a uno un disparador “{Q}”",
    "no object opens this room; give one an “{q}” trigger": "ningún objeto abre esta sala; dale a uno un disparador “{Q}”",
    "no tiles; no object opens this room": "sin losetas; ningún objeto abre esta sala",
    "Go to that room": "Ir a esa sala",
    "Open a room": "Abrir una sala",
    "Opens": "Abre",
    "a new room can be created here too.": "aquí también se puede crear una sala nueva.",
    "opened by “{q}”": "abierta por “{Q}”",
    "A scene (dialogue boxes)": "Una escena (cajas de diálogo)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Una escena de cajas de diálogo (como el flujo de la historia), tu propia película a pantalla completa, un efecto de sonido del juego o tu propio archivo de sonido. (una escena, un vídeo, un sonido)",
    "A sound (game effect or your own file)": "Un sonido (efecto del juego o tu propio archivo)",
    "A tile": "Una loseta",
    "A video (your own film)": "Un vídeo (tu propia película)",
    "Add / Remove…": "Añadir / Quitar…",
    "Add a trigger to “{q}”": "Añadir un disparador a “{Q}”",
    "Add or remove?": "¿Añadir o quitar?",
    "Add what?": "¿Añadir qué?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Añade a (o quita de) la reserva de ítems o la reserva de aparición de monstruos del mapa, durante el resto del mapa. (ítem, aparición de monstruos)",
    "Add…": "Añadir…",
    "An object": "Un objeto",
    "Cancel": "Cancelar",
    "Change item / spawn pool": "Cambiar la reserva de ítems / de aparición",
    "Change which pool?": "¿Cambiar qué reserva?",
    "Monster spawn": "Aparición de monstruos",
    "Play a scene, video or sound": "Reproducir una escena, un vídeo o un sonido",
    "Play what?": "¿Reproducir qué?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Pone algo en el tablero, o lo quita, durante la partida: losetas, objetos, monstruos, salas. (una loseta, un objeto, hacer aparecer monstruos, una loseta, una sala, un objeto, un monstruo)",
    "Remove…": "Quitar…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Algo aparece en el tablero: una loseta, un objeto o monstruos. (una loseta, un objeto, hacer aparecer monstruos)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Quita algo del tablero: una loseta, una sala, un objeto o monstruos. (una loseta, una sala, un objeto, un monstruo)",
    "What happens when a hero uses this object. Several triggers run in order.": "Lo que pasa cuando un héroe usa este objeto. Varios disparadores se ejecutan en orden.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Pone algo en el tablero, o lo quita, durante la partida: losetas, objetos, monstruos, salas. (una loseta, un objeto, una loseta, una sala, un objeto, un monstruo)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Lo que pasa una vez, cuando el recuento llega a {n} (el total del contador). Varios disparadores se ejecutan en orden.",
    "When the balanced group is defeated: “{q}”": "Cuando el grupo equilibrado es derrotado: “{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Una meta en este mapa, anunciada cuando el monstruo es derrotado y listada con los objetivos. Un objetivo no termina el mapa: lo hace la misión (Configurar mapa). Allí se puede elegir un objetivo como misión.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "Desde que el monstruo es derrotado, el contador de rondas ejecuta los disparadores de dentro: cada N rondas (tantas veces como digas, o hasta el final del mapa), o una vez, N rondas después. Para una oleada, pon “{Q}” dentro: la aparición tiene su propio “{Q}”.",
    "When this monster is defeated: “{q}”": "Cuando este monstruo es derrotado: “{Q}”",
    "If the test fails: “{q}”": "Si la prueba falla: “{Q}”",
    "After answer {n}: “{q}”": "Después de la respuesta {n}: “{Q}”",
    "When the rounds come: “{q}”": "Cuando lleguen las rondas: “{Q}”",
