    "Heal, damage, apply or remove a condition on a spawn group, on the monsters of this room or on all. Heroes are healed at the table (use a text).": "Cura, daña, aplica o quita un estado a un grupo de aparición, a los monstruos de esta sala o a todos. A los héroes se los cura en la mesa (usa un texto).",
