    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "Declarado en la mesa: la aplicación solo muestra el texto del objetivo entre los objetivos y no comprueba nada por sí sola. Cuenta como completado cuando la mesa lo marca en el panel de Bigorna del juego (F{n} → “{Q}”)",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "Declarado en la mesa: la aplicación solo muestra el texto del objetivo entre los objetivos y no comprueba nada por sí sola. Cuenta como completado cuando la mesa lo marca en el panel de Bigorna del juego (F{n} → “{Q}”); solo entonces vale el requisito “{Q}” y, si se eligió como misión, el mapa termina.",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "Dale a cada objeto que cuenta (cada llave, cada palanca) un disparador “{Q}” con este contador. La misión termina sola cuando se alcanza el número.",
