    "A counter of the map (see the “{q}” trigger, or the Counts button on the ribbon) must have reached a number: {n} keys found, all the seals broken…": "Un contador del mapa (mira el disparador “{Q}”, o el botón Recuentos de la barra) debe haber llegado a un número: {n} llaves encontradas, todos los sellos rotos…",
