    "This trigger runs only when every requirement holds; the other triggers of “{q}” are not held back. When one fails, the “{q}” triggers of this box run instead.": "Este disparador solo se ejecuta cuando se cumplen todos los requisitos; los demás disparadores de “{Q}” no se detienen. Cuando uno falla, se ejecutan en su lugar los disparadores “{Q}” de esta caja.",
    "the other triggers of “{q}” are not held back. When one fails, the “{q}” triggers of this box run instead.": "los demás disparadores de “{Q}” no se detienen. Cuando uno falla, se ejecutan en su lugar los disparadores “{Q}” de esta caja.",
