    ", part": ", parte",
    ": part": ": parte",
    ": pick a weapon, open one of its parts and change it, or create a new part for one of the three places. The weapon itself only keeps its name.": ": elige un arma, abre una de sus partes y cámbiala, o crea una parte nueva para uno de los tres lugares. El arma en sí solo conserva su nombre.",
    "A change applies while this map is played, to every copy of the part, also the ones bought or found later.": "Un cambio se aplica mientras se juega este mapa, a todas las copias de la parte, incluidas las que se compren o encuentren después.",
    "A different monster each time": "Un monstruo distinto cada vez",
    "A feat is a goal a hero pursues during the quests (attack with a spear {n} times, open {n} chests…). The game counts it by itself and gives the reward when it is done. Import the game’s feats (they stay as in the game; duplicate one to change it), or write new ones for any hero.": "Una proeza es una meta que un héroe persigue durante las misiones (atacar con una lanza {n} veces, abrir {n} cofres…). El juego la cuenta por sí solo y da la recompensa cuando se cumple. Importa las proezas del juego (quedan como en el juego; duplica una para cambiarla), o escribe nuevas para cualquier héroe.",
    "A new head of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Una cabeza nueva del Taller para esta arma: un ítem que el grupo recibe de un disparador o fabrica con una receta",
    "A new weapon in its place": "Un arma nueva en su lugar",
    "A recipe says what an item costs in crafting materials when the heroes craft it in the camp. Import the game’s recipes to change their costs, or write one for an item of the workshop. The party learns a recipe from a “{q}” trigger, or knows it from the start.": "Una receta dice cuánto cuesta un ítem en materiales de creación cuando los héroes lo fabrican en el campamento. Importa las recetas del juego para cambiar sus costes, o escribe una para un ítem del Taller. El grupo aprende una receta con un disparador “{Q}”, o la conoce desde el principio.",
    "A skill card is unlocked for the hero (the physical card at the table)": "Se desbloquea una carta de habilidad para el héroe (la carta física en la mesa)",
    "A skill card is unlocked for the hero (the physical card at the table); a recipe is learned by the party.": "Se desbloquea una carta de habilidad para el héroe (la carta física en la mesa); el grupo aprende una receta.",
    "A workshop tile is your own physical piece: once per room, reusing it in another room asks to remove the earlier one, and it takes pillars in its sockets (between two squares on a straight edge) when elevated. In the app the mod builds it as a flat tile of this shape, with your picture or colour, and the heroes walk on it like on any tile.": "Una loseta del Taller es tu propia pieza física: una vez por sala, reutilizarla en otra sala pide quitar la anterior, y admite pilares en sus encajes (entre dos casillas en un borde recto) cuando está elevada. En la aplicación el mod la construye como una loseta plana con esta forma, con tu imagen o color, y los héroes caminan sobre ella como sobre cualquier loseta.",
