    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Los seis perfiles del juego (clase, armas, habilidades y proezas) entran en la campaña. Cada uno lo juega el héroe del juego (como en el juego) o un héroe de tu plantilla, asignado a él en la propia ficha del héroe.",
