    "(the profile’s)": "(la del perfil)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Cada arma tiene un héroe en el juego (sus partes, la tienda, el inventario y las proezas lo siguen). Elegir el arma de otro héroe le entrega esta a cambio. Los números vienen de las armas: se cambian en la pestaña Armas. Las armas pertenecen al perfil: se quedan con él si el héroe se va.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "Las armas pertenecen al perfil: se quedan con él si el héroe se va.",
    "went back to the roster.": "ha vuelto a la plantilla.",
