    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Arrastra las piezas para montar el arma como la quieras; la rueda (o el deslizador) cambia el tamaño de la pieza elegida, Mayús+rueda, Q/E o el deslizador de giro la rotan, las flechas la desplazan. Una pieza solo se ve dentro de su propia caja: lo que sale de ella se corta (se ve tenue).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Arrastra las piezas para montar el arma, forja la plantilla y genera las imágenes",
