    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "Elige un tipo de arma, luego sus cabezas, astas o empuñaduras. Lo que cambies se aplica mientras se juega este mapa (a todas las copias de la parte, incluidas las que se compren o encuentren después)",
