    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Pociones y cartas de un solo uso que los héroes gastan durante una misión. Solo los ítems listados en el Taller pueden darse con disparadores, recompensas y diálogos, soltarse como botín de monstruos o fabricarse.",
