    "What the monster does on its turn, in order; “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "Lo que hace el monstruo en su turno, en orden; “{Q}” las encadena. Velocidad, daño, puntería, ataque, alcance, curación, escudo, iniciativa y tipo de alcance son los números que usa la aplicación; el texto es lo que leen los jugadores.",
