    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Escribe texto sin formato. Los botones ponen los nombres que rellena la aplicación ([monster] = el nombre de este monstruo, [hero] = el nombre del héroe al que apunta (u otro nombre que rellene la aplicación)) y los iconos del juego. Las palabras de regla como cicatrizar, aterrorizar o concentrado se convierten solas en los términos resaltados del juego.",
