    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "Cajas de texto, preguntas y vídeos (tus propias películas), reproducidas seguidas (va después de la tarjeta seleccionada)",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Cajas de “{Q}”: arrastra desde el ● de una caja (o el ● de una respuesta) hasta otra caja para decir qué viene después",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "Las cajas se reproducen en el orden de las flechas, empezando por la primera. Una caja de pregunta ramifica: cada respuesta lleva a su propia caja siguiente. Una caja de vídeo reproduce tu propia película (MP{n} o WebM) entre las otras cajas.",
    "Build the rooms of this map": "Construir las salas de este mapa",
    "Build the rooms of this side quest": "Construir las salas de esta misión secundaria",
    "Build the rooms ▸": "Construir las salas ▸",
    "Campaign ▸": "Campaña ▸",
    "City": "Ciudad",
