    "Comes after (arrows into it)": "Viene después de (flechas que entran)",
    "Crafting materials": "Materiales de creación",
    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "la campana cuelga de su soporte: una campana en la mesa ocupa el soporte, y con un solo soporte solo cuelga una campana a la vez",
