    "Erase the campaign, all its maps and its workshop from the editor": "Borra del editor la campaña, todos sus mapas y su Taller",
    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Cada mapa, misión secundaria y parada tiene un lugar aquí y un tipo de marcador: misión principal, misión secundaria, evento narrativo o visita a la ciudad.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Todo lo de esta campaña se borra del editor, y no se puede deshacer:",
    "Export campaign": "Exportar campaña",
    "Export, then delete": "Exportar y luego borrar",
    "Files already exported stay in the folder": "Los archivos ya exportados siguen en la carpeta",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "Los archivos ya exportados siguen en la carpeta; bórralos allí si quieres. El guardado automático deja de seguir esta campaña, así que no los borrará. El juego conserva el progreso de cualquier grupo que la haya jugado.",
    "Fit the whole flow in the view": "Encuadrar todo el flujo en la vista",
