    "New variable (Spared the bandit, Sided with the rebels…)": "Variable nueva (Perdonó al bandido, Se puso del lado de los rebeldes…)",
    "No remembered choice yet: in a question box, tick “{q}”.": "Aún no hay elecciones recordadas: en una caja de pregunta, marca “{Q}”.",
    "On the world map as": "En el mapa del mundo como",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG o JPG, {n}:{n} ({n}×{n} encaja exactamente). Cubre todo el marco que muestra el juego",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG o JPG, {n}:{n} ({n}×{n} encaja exactamente). Cubre todo el marco que muestra el juego; el agua, la tierra quemada, los nombres de lugares y los caminos del juego se ocultan. La niebla cubre una región fija del propio mapa del juego (las Mistlands).",
    "Place this waypoint on the world map": "Coloca esta parada en el mapa del mundo",
    "Plays as": "Se reproduce como",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Apunta a una línea para iluminar su flecha. Para ver adónde lleva una tarjeta, haz clic en su ●.",
    "Remember a choice": "Recordar una elección",
    "Remember this answer": "Recordar esta respuesta",
    "Remove this arrow": "Quitar esta flecha",
