    "Side quest {n}": "Misión secundaria {n}",
    "Simulation": "Simulación",
    "Stay and fill them": "Quedarse y rellenarlas",
    "Story flow": "Flujo de la historia",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Las elecciones que la campaña recuerda de un mapa al siguiente: perdonó al bandido, se puso del lado de los rebeldes, tomó el anillo maldito… Una elección se define cuando el grupo elige una respuesta marcada con “{Q}” (o con una acción “{Q}”) y se mantiene el resto de la campaña. Las tarjetas del flujo de la historia y los disparadores de los mapas pueden depender entonces de que el grupo la haya hecho o no.",
    "The party moves on the world map (it goes after the selected card)": "El grupo se mueve en el mapa del mundo (va después de la tarjeta seleccionada)",
    "The scene goes on with the next box when the film ends.": "La escena sigue con la siguiente caja cuando termina la película.",
    "Then:": "Luego:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Se exportan tal como están. Rellénalas, o borra las que no necesites.",
    "Type the name of the campaign to confirm:": "Escribe el nombre de la campaña para confirmar:",
