    "Writes the .bcamp and its maps (download), then deletes.": "Escribe el .bcamp y sus mapas (descarga) y luego borra.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Estás construyendo las salas de este mapa. Elige otro mapa, o añade mapas, paradas y diálogos, en la pantalla de la campaña (“{Q}” arriba).",
    "after Map {n}": "después del Mapa {n}",
