    "narrator": "narrador",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "aún no depende nada de ella: elígela en “{Q}” de una tarjeta, o como el requisito “{Q}” de un disparador de mapa.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "aún no la define nada: marca “{Q}” en una caja de pregunta y dale este nombre. Hasta entonces “{Q}” nunca es verdadera.",
    "only a question may branch": "solo una pregunta puede ramificar",
    "progression {n}": "progresión {n}",
    "question": "pregunta",
    "the name is yours.": "el nombre es tuyo.",
    "the scenes that follow it play in the same visit.": "las escenas que la siguen se reproducen en la misma visita.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "el flujo de la historia: {n} tarjeta(s), {n} escena(s) con sus cajas, {n} variable(s) de la historia",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "el Taller: {n} monstruo(s), {n} PNJ, {n} ítem(s), {n} héroe(s), {n} arma(s), {n} receta(s), {n} proeza(s), {n} loseta(s)/objeto(s) propios",
    "the world map positions, the rewards, the music and videos chosen": "las posiciones en el mapa del mundo, las recompensas, la música y los vídeos elegidos",
