    "without a name": "sin nombre",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "{n} caja(s): texto, preguntas y vídeos (tus propias películas), reproducidos uno tras otro en el mismo marco. Se reproduce en este punto de la historia: después de un mapa es la escena final del mapa",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "{n} caja(s): texto, preguntas y vídeos (tus propias películas), reproducidos uno tras otro en el mismo marco. Se reproduce en este punto de la historia: después de un mapa es la escena final del mapa; después de una parada se reproduce al llegar; antes de todo, abre la campaña.",
