    "✦ Generate map (experimental)": "✦ Generar mapa (experimental)",
    "Generate a map (experimental)": "Generar un mapa (experimental)",
    "Original maps": "Mapas originales",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "El mod Bigorna lee los mapas originales del juego de tu propia copia del juego: arranca el juego una vez con el mod instalado (la pantalla de título los prepara) y luego abre de nuevo el editor desde la carpeta Editor del juego.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Las misiones del juego, convertidas en mapas del editor: losetas, objetos, salas, monstruos y la lógica que pueden expresar los disparadores.",
    "Each map comes with notes on what was simplified (Map setup).": "Cada mapa viene con notas sobre lo que se simplificó (Configurar mapa).",
