    "lever to the attic": "palanca al desván",
    "viaduct": "viaducto",
    "🧱 Pieces in your boxes…": "🧱 Piezas en tus cajas…",
    "How many of each piece you have: the generators use only these, and the object buttons show how many are on the table while a room is open. A blank field uses the estimate for your boxes (shown faded); ∞ means no limit. Two boxes, or a piece made by hand: raise the number.": "Cuántas piezas de cada tipo tienes: los generadores solo usan esas, y los botones de objeto muestran cuántas hay en la mesa mientras hay una sala abierta. Un campo en blanco usa la estimación para tus cajas (se ve tenue); ∞ significa sin límite. ¿Dos cajas, o una pieza hecha a mano? Sube el número.",
    "3D objects and tokens": "Objetos 3D y fichas",
