    "Update": "Actualizar",
    "Workshop packages shared by other authors. A package downloaded here goes into your library (⚙ → My packages), ready to add to any map or campaign.": "Paquetes del Taller compartidos por otros autores. Un paquete descargado aquí va a tu biblioteca (⚙ → Mis paquetes), listo para añadir a cualquier mapa o campaña.",
    "a new edition of what is in the community library": "una edición nueva de lo que hay en la biblioteca de la comunidad",
