    "not in your library": "no está en tu biblioteca",
    "of this package. Make a new edition first: ⚙ → Export a package → “New edition of …”.": "de este paquete. Haz primero una edición nueva: ⚙ → Exportar un paquete → “Nueva edición de …”.",
    "the card inside the file is not this one": "la tarjeta dentro del archivo no es esta",
