    "this campaign": "esta campaña",
    "this map": "este mapa",
    "was saved (in Downloads, or the folder of your browser).": "se guardó (en Descargas, o en la carpeta de tu navegador).",
    "your library has edition": "tu biblioteca tiene la edición",
    "your library has": "tu biblioteca tiene",
    "Package": "Paquete",
    "✎ Stats": "✎ Estadísticas",
    "Underlay cards": "Cartas de capa inferior",
    "This belongs to the package": "Esto pertenece al paquete",
    "Change it: a version of yours, with a new ID": "Cambiarla: una versión tuya, con un ID nuevo",
    "Create a clone": "Crear un clon",
    "The package’s entry stays as the creator made it.": "La entrada del paquete queda como la hizo el creador.",
    "Clone made: it is yours to change.": "Clon creado: ya puedes cambiarlo.",
    "Now this version is yours, with a new ID: change it here.": "Ahora esta versión es tuya, con un ID nuevo: cámbiala aquí.",
    "An original of the game: it stays as the game has it.": "Un original del juego: queda como lo tiene el juego.",
    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "Cámbialo aquí: al cambiarlo pasa a ser tuyo, con el mismo id (lo que lo usa recibe tu versión; el archivo del paquete queda como está). Para quitarlo, quita el paquete (📚 Mis paquetes).",
    "It replaces the map on screen, fully editable.": "Reemplaza el mapa en pantalla, totalmente editable.",
    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "Un mapa entero: por qué entran los héroes (premisa), qué deben hacer para ganar (objetivo), qué cambia por el camino (regla extra), cómo crece la tensión y el final. Reemplaza el mapa en pantalla, totalmente editable.",
    "Add to the campaign": "Añadir a la campaña",
    "Monsters in a room": "Monstruos en una sala",
    "A long, narrow way: whoever holds the narrow part holds the room.": "Un camino largo y estrecho: quien domina la parte estrecha domina la sala.",
    "Wide and open: a straight fight with room to move.": "Amplia y abierta: un combate directo con espacio para moverse.",
    "Few or no monsters, several points of interest to search and a clue.": "Pocos o ningún monstruo, varios puntos de interés que registrar y una pista.",
    "The reward, guarded or not: chests at the back, a price to reach them.": "La recompensa, vigilada o no: cofres al fondo, un precio para llegar a ellos.",
    "A calm place to breathe, heal and talk: no monsters, a little to find.": "Un lugar tranquilo para respirar, curarse y hablar: sin monstruos, algo que encontrar.",
    "The last room: large, with cover and a strong foe at the back.": "La última sala: grande, con cobertura y un enemigo fuerte al fondo.",
    "The way is blocked by water, fire or rubble: go around, or through it.": "El camino está bloqueado por agua, fuego o escombros: rodéalo, o atraviésalo.",
    "A raised platform over the floor: whoever holds the height sees everything.": "Una plataforma elevada sobre el suelo: quien domina la altura lo ve todo.",
    "Moving: drag the room · R turns it · Esc or a click outside ends it": "Moviendo: arrastra la sala · R la gira · Esc o un clic fuera termina",
    "Click the outline to move the room · R turns it": "Haz clic en el contorno para mover la sala · R la gira",
    "The room has no tiles to turn.": "La sala no tiene losetas que girar.",
    "Turned, the room overlapped another one: it stayed as it was.": "Al girarla, la sala se superponía a otra: se quedó como estaba.",
    "Room turned 90°, with everything in it.": "Sala girada 90°, con todo lo que contiene.",
    "Delete anyway": "Borrar de todos modos",
