    "Skills with no hero (cards only)": "Habilidades sin héroe (solo cartas)",
    "The skills of this hero, by XP": "Las habilidades de este héroe, por XP",
    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Esto borra todo lo que guarda el editor: el mapa o la campaña en pantalla, el Taller (monstruos, ítems, materiales, objetos, importados o hechos), los paquetes (en la aplicación: la carpeta Pacotes, todos los paquetes que contiene), las imágenes guardadas por el editor, el guardado rápido, tus arquetipos, las pistas y avisos, las posiciones y tamaños de las ventanas, el autor, la carpeta de exportación y el guardado automático.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "Restablecer todo: el trabajo en pantalla, el Taller y los paquetes, las imágenes guardadas, el guardado rápido, los arquetipos, las pistas y avisos, las posiciones y tamaños de las ventanas, el autor, la carpeta de exportación y el guardado automático. El idioma se mantiene.",
