    "it stands on the floor, with its walls 2 above it. It takes no pillars; it may stand on the game box (all its squares over the box).": "está sobre el suelo, con sus muros 2 por encima. No admite pilares; puede ir sobre la caja del juego (todas sus casillas sobre la caja).",
