    "A round counts one when it happens that many times in the same round.": "Una ronda cuenta uno cuando ocurre esas veces en la misma ronda.",
    "Any health (always counts)": "Cualquier vida (siempre cuenta)",
    "Counts only against a monster that has this condition at that moment.": "Cuenta solo contra un monstruo que tiene este estado en ese momento.",
    "Counts only against a monster with at least this many conditions at once.": "Cuenta solo contra un monstruo con al menos esta cantidad de estados a la vez.",
    "Counts only against monsters of one of the ticked kinds.": "Cuenta solo contra monstruos de uno de los tipos marcados.",
    "Counts only an attack that deals at least this much damage.": "Cuenta solo un ataque que hace al menos este daño.",
