    "Counts only interactions with this kind of object. Without this condition, every object counts except the sight tokens.": "Cuenta solo las interacciones con este tipo de objeto. Sin esta condición, cuentan todos los objetos excepto las fichas de Vista.",
    "Counts only the items of the ticked kinds.": "Cuenta solo los ítems de los tipos marcados.",
    "Counts only when the object leaves the board with the interaction (a chest opened and gone, a token taken, a fire put out).": "Cuenta solo cuando el objeto sale del tablero con la interacción (un cofre abierto y retirado, una ficha tomada, un fuego apagado).",
    "Counts only while the hero fights with a weapon of one of the ticked kinds (the one in hand at that moment).": "Cuenta solo mientras el héroe combate con un arma de uno de los tipos marcados (la que tiene en la mano en ese momento).",
    "Counts only while there are at least this many monsters on the map.": "Cuenta solo mientras hay al menos esta cantidad de monstruos en el mapa.",
    "Each time the moment comes and every condition holds, it counts one.": "Cada vez que llega el momento y se cumplen todas las condiciones, cuenta uno.",
    "Has at least a major injury": "Tiene al menos una dolencia grave",
