    "Only the damage that comes from the monster’s weaknesses is added up.": "Solo se suma el daño que viene de las debilidades del monstruo.",
    "Pick the reward": "Elige la recompensa",
    "Reward…": "Recompensa…",
    "Skill cards of": "Cartas de habilidad de",
    "The damage of each counted attack is added up until it reaches the goal.": "El daño de cada ataque contado se suma hasta llegar a la meta.",
    "The hero’s health at that moment. “At least” also counts a worse state (a major injury is at least a minor one); “exactly” counts that state only.": "La vida del héroe en ese momento. “Al menos” también cuenta un estado peor (una dolencia grave es al menos una leve); “exactamente” cuenta solo ese estado.",
    "Whether another hero has also attacked this monster.": "Si otro héroe también ha atacado a este monstruo.",
    "Whether every hero of the party, this one included, has already attacked this round.": "Si todos los héroes del grupo, este incluido, ya han atacado en esta ronda.",
    "Whether every other hero of the party has already attacked this round.": "Si todos los demás héroes del grupo ya han atacado en esta ronda.",
    "Whether some hero has already attacked this round. “Before” counts only the first attack of the round.": "Si algún héroe ya ha atacado en esta ronda. “Antes” cuenta solo el primer ataque de la ronda.",
    "Whether some hero has already interacted this round. “Before” counts only the first interaction of the round.": "Si algún héroe ya ha interactuado en esta ronda. “Antes” cuenta solo la primera interacción de la ronda.",
    "Whether some hero other than this one has an injury at that moment.": "Si algún héroe distinto de este tiene una dolencia en ese momento.",
