    "Use the game’s": "Usar la del juego",
    "+ Add to the roll": "+ Añadir a la tirada",
    "In the app this weapon is turned {n}°; the boxes show it.": "En la aplicación esta arma está girada {n}°; las cajas lo muestran.",
    "Click: into the forge · double click: its stats": "Clic: a la forja · doble clic: sus estadísticas",
    "Its stats": "Sus estadísticas",
    "Its stats (a part of the game: duplicate it to change it)": "Sus estadísticas (una parte del juego: duplícala para cambiarla)",
    "of the game": "del juego",
    "Pick the parts in the middle column (a double click, or ✎, opens the stats of one). The parts of the game stay as they are; the ones of the workshop move: drag them, the wheel (or the slider) changes the size, Shift+wheel, Q/E or the turn slider rotate, the arrows nudge.": "Elige las partes en la columna del medio (un doble clic, o ✎, abre las estadísticas de una). Las partes del juego quedan como están; las del Taller se mueven: arrástralas, la rueda (o el deslizador) cambia el tamaño, Mayús+rueda, Q/E o el deslizador de giro las rotan, las flechas las desplazan.",
    "keeps each moved piece where it is: its box (where the app draws it) goes with it, and the piece becomes a picture of that box. “Game’s template” undoes what was forged.": "conserva cada pieza movida donde está: su caja (donde la dibuja la aplicación) va con ella, y la pieza pasa a ser una imagen de esa caja. “Plantilla del juego” deshace lo que se forjó.",
    "A part of the game stays as it is: duplicate it (✎) to move one of your own.": "Una parte del juego queda como está: duplícala (✎) para mover una tuya.",
    "Back to the game’s template: what was forged is undone.": "De vuelta a la plantilla del juego: se ha deshecho lo forjado.",
    "Forged: the parts of the workshop stay where you left them, in the game too.": "Forjado: las partes del Taller se quedan donde las dejaste, también en el juego.",
    "Chance": "Probabilidad",
    "Duplicated: this part is yours to change.": "Duplicada: ahora esta parte es tuya y puedes cambiarla.",
    "+ Box with options": "+ Caja con opciones",
    "A box with answers: each one leads to its own next box": "Una caja con respuestas: cada una lleva a su propia caja siguiente",
    "Lay the boxes out left to right, in the order of the arrows": "Colocar las cajas de izquierda a derecha, en el orden de las flechas",
    "The number the objective and the consequence wait for": "El número que esperan el objetivo y la consecuencia",
    "An objective of the map: completed when the count reaches": "Un objetivo del mapa: completado cuando el recuento llega a",
    "Starts at 0": "Empieza en 0",
    "limit": "límite",
    "Limit": "Límite",
    "The count never goes above this number. Empty: no limit. It always starts at 0.": "El recuento nunca pasa de este número. Vacío: sin límite. Siempre empieza en 0.",
    "? (no longer in the workshop)": "? (ya no está en el Taller)",
    "Open it to change it": "Ábrelo para cambiarlo",
    "Remove this consequence?": "¿Quitar esta consecuencia?",
    "Counter “{q}” counts rounds by itself: pick the number its objective waits for (Counts button).": "El contador “{Q}” cuenta rondas solo: elige el número que espera su objetivo (botón Recuentos).",
    "Counter “{q}” counts monsters by itself: pick the number its objective waits for (Counts button).": "El contador “{Q}” cuenta monstruos solo: elige el número que espera su objetivo (botón Recuentos).",
    "What happens once, when the count reaches {n}. Several triggers run in order.": "Lo que pasa una vez, cuando el recuento llega a {n}. Varios disparadores se ejecutan en orden.",
    "the number the counter’s objective waits for (Counts button)": "el número que espera el objetivo del contador (botón Recuentos)",
    "[count] is the name of the counter (highlighted like the rule words of the game), [n] the count after this trigger, [total] the number its objective waits for (Counts button). Missions and requirements can wait for the counter to reach a number (“{q}”).": "[count] es el nombre del contador (resaltado como las palabras de regla del juego), [n] el recuento después de este disparador, [total] el número que espera su objetivo (botón Recuentos). Las misiones y los requisitos pueden esperar a que el contador llegue a un número (“{Q}”).",
    "not in the workshop!": "¡no está en el Taller!",
    "Item…": "Ítem…",
    "original of the game": "original del juego",
    "An original of the game: its name, numbers, activations, tactics and defense stay as in the game. Duplicate it (with another name) to make a monster of your own from it. The pictures, the loot and the sounds may change here.": "Un original del juego: su nombre, números, activaciones, tácticas y defensa quedan como en el juego. Duplícalo (con otro nombre) para hacer un monstruo tuyo a partir de él. Las imágenes, el botín y los sonidos pueden cambiar aquí.",
    "The figure, animations and behaviour family in the app.": "La figura, las animaciones y la familia de comportamiento en la aplicación.",
    "The order counts:": "El orden cuenta:",
    "the monster does its activations in this order (1 first); ↑ ↓ change it. “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "el monstruo hace sus activaciones en este orden (1 primero); ↑ ↓ lo cambian. “{Q}” las encadena. Velocidad, daño, puntería, ataque, alcance, curación, escudo, iniciativa y tipo de alcance son los números que usa la aplicación; el texto es lo que leen los jugadores.",
